window.AUTH=window.AUTH||{};window.AUTH["17-2"]={"d":"17-2","id":"2017/17-2","n":"United States v. Microsoft Corporation","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2017-12-06","url":"https://www.supremecourt.gov/DocketPDF/17/17-2/22902/20171206191900398_17-2tsUnitedStates.pdf","side":"pet","n":88},{"k":"respondent","label":"Brief of respondent Microsoft Corporation","date":"2018-01-11","url":"https://www.supremecourt.gov/DocketPDF/17/17-2/27619/20180111205746909_Brief%20for%20Respondent%202018.01.11.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner United States","date":"2018-02-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-2/35221/20180212181405680_17-2rbUnitedStates.pdf","side":"pet","n":45}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Birchfield v. North Dakota","cite":"136 S. Ct. 2160","y":2016,"id":"2015/14-1468","sc":1,"sum":"The Court determined that warrantless blood tests incident to an arrest for drunk driving violate the Fourth Amendment, but warrantless breath tests incident to an arrest for drunk driving do not.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Braswell v. United States","cite":"487 U.S. 99","y":1988,"id":"1987/87-3","sc":1,"sum":"The Supreme Court held that corporations are not protected by the Fifth Amendment privilege against self-incrimination. An agent of the corporation holds the official records of the corporation in their representative, and not individual, capacity so the personal privilege is not applicable.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"California v. Hodari D.","cite":"499 U.S. 621","y":1991,"id":"1990/89-1632","sc":1,"sum":"The Supreme Court held that a Fourth Amendment seizure requires some sort of physical force with lawful authority, or submission to an assertion of authority. Hodari had not been touched when he discarded the cocaine, and had not submitted to authority because he was still attempting to escape.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"(III) Cases—Continued: California Bankers Assn. v. Shultz","cite":"416 U.S. 21","y":1974,"id":"1973/72-985","sc":1,"sum":"The Bank Secrecy Act of 1970, which was enacted following extensive hearings concerning the unavailability of foreign and domestic bank records of customers thought to be engaged in illegal activities, authorizes the. Secretary of the Treasury to prescribe by regulation ceftain bank recordkeeping and reporting iequirements, the Act's penaltes attaching only upon violation of the regulations thus prescribed. (Unless …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"33"}},{"t":"case","label":"City of L.A. v. Patel","cite":"135 S. Ct. 2443","y":2015,"id":"2014/13-1175","sc":1,"sum":"The Court determined that a municipal ordinance that allows the police to inspect hotel records without a warrant violates the Fourth Amendment’s prohibition against unreasonable searches unless the business owner is given the opportunity for pre-compliance review.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Donovan v. Lone Steer, Inc.","cite":"464 U.S. 408","y":1984,"id":"1983/82-1684","sc":1,"sum":"The subpoena duces tecum did not violate the Fourth Amendment. Oklahoma Press PublishingCo. v. Walling, 327 U. S. 186, controlling. An entry into the public lobby of a motel and restaurant for the purpose of serving an administrative subpoena is not the sort of governmental act that is forbidden by that Amendment. Here, the subpoena itself did not authorize either entry or inspection of appellee's premises but …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"48"}},{"t":"case","label":"Fisher v. United States","cite":"425 U.S. 391","y":1976,"id":"1975/74-18","sc":1,"sum":"In each of these cases taxpayers, who were under investigation for possible civil or criminal liability under the federal income tax laws, after having obtained from their respective accountants certain documents relating to the accountants' preparation of their tax returns, transferred the documents to their respective attorneys to assist the taxpayers in connection with the investigations. Subsequently, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"50"}},{"t":"case","label":"Gambino v. United States","cite":"275 U.S. 310","y":1927,"id":"scdb/1927-031","sc":1,"sum":"1. The term “any officer of the law” in § 26, Title II of the National Prohibition Act, refers only to federal officers.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"29","2":"11"}},{"t":"case","label":"Hay Grp., Inc. v. E.B.S. Acquisition Corp.","cite":"360 F.3d 404","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/360/404/","sum":"Explaining that subpoenaed documents are produced “not [in] the district in which the documents are housed but [in] the district in which the subpoenaed party is required to turn them over”.","sumSrc":"brief:0","by":{"0":"32","2":"16"}},{"t":"case","label":"Kastigar v. United States","cite":"406 U.S. 441","y":1972,"id":"1971/70-117","sc":1,"sum":"The Court found that compelled testimony is legitimate given the grant of immunity. Justice Powell found that the protections of immunity that a congressional statute provided were \"coextensive with the scope of the privilege against self-incrimination\" and \"sufficient to compel testimony over a claim of the privilege.\".","sumSrc":"Oyez","by":{"0":"30","2":"11"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"46","1":"14, 24","2":"1"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"0":"32","2":"17"}},{"t":"case","label":"Linde v. Arab Bank, PLC","cite":"706 F.3d 92","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/706/92/","by":{"0":"51"}},{"t":"case","label":"Liu Meng-Lin v. Siemens AG","cite":"763 F.3d 175","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/763/175/","sum":"Rejecting the argument that all provisions of a statutory scheme must apply extraterritorially.","sumSrc":"brief:0","by":{"0":"20"}},{"t":"case","label":"Loginovskaya v. Batratchenko","cite":"764 F.3d 266","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/764/266/","sum":"Concluding that the focus of one provision is “clearly transactional,” while acknowledging that a separate provision of the same statute has an “apparent focus on the persons who are regulated without regard to where the resulting transaction occurs”.","sumSrc":"brief:0","by":{"0":"20"}},{"t":"case","label":"Los Angeles Cnty. v. Rettele","cite":"550 U.S. 609","y":2007,"id":"2006/06-605","sc":1,"sum":"The Court decided that a search conducted on a home when the race of the occupants does not match the race of the supposed occupants identified in the search warrant does not violate the occupant’s Fourth Amendment rights.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Maracich v. Spears","cite":"133 S. Ct. 2191","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Marc Rich & Co. v. United States","cite":"707 F.2d 663","y":1983,"url":"https://www.courtlistener.com/c/F.2d/707/663/","sum":"Holding that “service of a subpoena upon [a company’s] officers within the territorial boundaries of the United States would be sufficient to warrant judicial enforcement,” regardless of whether “the documents are located abroad”.","sumSrc":"brief:0","by":{"0":"7, 14, 33","1":"44","2":"15"}},{"t":"case","label":"Microsoft Corp. v. AT&T Corp.","cite":"550 U.S. 437","y":2007,"id":"2006/05-1056","sc":1,"sum":"The Court ruled 7-1 that Microsoft was not liable for infringement of AT&T's patent. The opinion by Justice Ruth Bader Ginsburg held that \"software code is an idea without physical embodiment\"; it cannot be a component of a patented invention.","sumSrc":"Oyez","by":{"0":"17","1":"2, 27, 39"}},{"t":"case","label":"Morrison v. National Austl. Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"ar":2,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"0":"13, 17, 18, 19, 20, 23","1":"9, 14, 20, 25, 28, 30, 37, 50","2":"1, 2, 3, 4, 5"}},{"t":"case","label":"Oklahoma Press Publ’g Co. v. Walling","cite":"327 U.S. 186","y":1946,"id":"scdb/1945-112","sc":1,"sum":"1. The Fair Labor Standards Act, as applied to the business of publishing and distributing newspapers, does not violate the First or Fifth Amendment or exceed the power of Congress under the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"48, 51"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"passim","1":"15, 18, 20, 25, 30, 39, 40","2":"2, 3, 4, 5"}},{"t":"case","label":"Reinsurance Co. of Am., Inc. v. Administratia Asgurarilor de Stat","cite":"902 F.2d 1275","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/902/1275/","by":{"0":"51"}},{"t":"case","label":"Securities and Exchange Comm’n v. Minas de Artemisa","cite":"150 F.2d 215","y":1945,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/150/215/","by":{"0":"34"}},{"t":"case","label":"Skinner v. Railway Labor Execs.’ Ass’n","cite":"489 U.S. 602","y":1989,"id":"1988/87-1555","sc":1,"sum":"The Court held that the government's interest in assuring safety on the nation's railroads constituted a \"special need\" which justified a departure from standard warrant and probable-cause requirements in searches.","sumSrc":"Oyez","by":{"0":"29","1":"33","2":"10"}},{"t":"case","label":"Societe Internationale pour Participations Industrielles et Commerciales, S. A. v. Rogers","cite":"357 U.S. 197","y":1958,"id":"1957/348","sc":1,"ar":2,"sum":"In a suit under § 9 (a) of the Trading with the Enemy Act brought by petitioner, a Swiss holding company, for the return of property seized by the Alien Property Custodian under § 5 (b), the District Court ordered petitioner to produce certain records of petitioner's Swiss bank. The Court found the records to be relevant and to be within petitioner's \"control,\" within the meaning of Rule 34 of.the Federal Rules of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"52","2":"22"}},{"t":"case","label":"Société Nationale Industrielle Aérospatiale v. United States Dist. Court","cite":"482 U.S. 522","y":1987,"id":"1986/85-1695","sc":1,"sum":"The United States, France, and 15 other countries have acceded to the Hague Evidence Convention, which prescribes procedures by which a judicial authority in one contracting state may request evidence located in another. Plaintiffs brought suits (later consolidated) in Federal District Court for personal injuries resulting from the crash of an aircraft built and sold by petitioners, two corporations owned by France. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 51","1":"50","2":"17"}},{"t":"case","label":"Soldal v. Cook Cnty.","cite":"506 U.S. 56","y":1992,"id":"1992/91-6516","sc":1,"sum":"The seizure and removal of the trailer home implicated petitioners' Fourth Amendment rights.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31"}},{"t":"case","label":"Superintendent of Ins. of N.Y. v. Bankers Life & Cas. Co.","cite":"404 U.S. 6","y":1971,"id":"1971/70-60","sc":1,"sum":"Section 10 (b) of the Securities Exchange Act of 1934 makes it unlawful to use \"in connection with the purchase or sale\" of any security \"any manipulative or deceptive device or contrivance\" in contravention of the Securities and Exchange Commission's rules and regulations. Section 10 (b) prohibits the use of any deceptive device in the \"sale\" of any security by \"any person,\" and it is irrelevant that Manhattan was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 23"}},{"t":"case","label":"TianRui Grp. v. Int’l Trade Comm’n","cite":"661 F.3d 1322","y":2011,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/661/1322/","sum":"Concluding that the “focus” of a particular statutory provision is “on the act of importation and the resulting domestic injury”.","sumSrc":"brief:0","by":{"0":"20"}},{"t":"case","label":"United States v. All Assets Held at Bank Julius","cite":"251 F. Supp. 3d 82","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/251/82/","by":{"0":"20"}},{"t":"case","label":"United States v. Ballestas","cite":"795 F.3d 138","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/795/138/","sum":"Noting that “the extraterritorial reach of a particular provision will not necessarily be imputed to an entire statute”.","sumSrc":"brief:0","by":{"0":"20"}},{"t":"case","label":"United States v. Bank of Nova Scotia","cite":"740 F.2d 817","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/740/817/","by":{"0":"33"}},{"t":"case","label":"United States v. Barr","cite":"605 F. Supp. 114","y":1985,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./605/114/","sum":"Upholding subpoena requiring mail delivery service to turn over a client’s letters.","sumSrc":"brief:0","by":{"0":"41","2":"16"}},{"t":"case","label":"United States v. First Nat’l City Bank","cite":"396 F.2d 897","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/396/897/","ar":2,"by":{"0":"33, 34","1":"51","2":"13"}},{"t":"case","label":"United States v. Grubbs","cite":"547 U.S. 90","y":2006,"id":"2005/04-1414","sc":1,"ar":1,"sum":"Justice Antonin Scalia, in the majority opinion, wrote that under the Fourth Amendment's particularity requirement a warrant need not set out the conditions that trigger it, only the place to be searched and the persons or things to be searched for. The fact that the triggering conditions were included in the affidavit, even if they were never showed to Grubbs, was therefore sufficient.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"United States v. Hubbell","cite":"530 U.S. 27","y":2000,"id":"1999/99-166","sc":1,"sum":"The Court, in order to determine the precise scope of a grant of immunity with respect to the production of documents in response to a subpoena, held that a person responding to subpoena, pursuant to a court order granting immunity, could not be prosecuted on the basis of information in the documents produced if the government did not have any prior, independent knowledge of the documents.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"United States v. Jacobsen","cite":"466 U.S. 109","y":1984,"id":"1983/82-1167","sc":1,"sum":"The Court held that the initial inspection by the DEA agent did not violate the Fourth Amendment because it remained within the scope of the previous search conducted by private agents. Once the agents gained enough information about the package to believe it contained contraband, the warrantless seizure of the package and its contents was not unreasonable.","sumSrc":"Oyez","by":{"0":"30, 31","1":"34","2":"12"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Zurcher v. Stanford Daily","cite":"436 U.S. 547","y":1978,"id":"1977/76-1484","sc":1,"sum":"In a 5-to-3 decision, the Court held that the \"third party\" search of the newsroom did not violate the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"30"}},{"t":"usc","label":"18 U.S.C. § 2510","url":"https://www.law.cornell.edu/uscode/text/18/2510","subs":["(15)"],"by":{"0":"2, 2"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","by":{"0":"18"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(a)","(b)","(c)","(d)"],"by":{"0":"18, 19, 18, 18, 18, 18"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","subs":["(c)"],"stext":{"head":"§1964. Civil remedies","paras":[[0,"(a) The district courts of the United States shall have jurisdiction to prevent and restrain violations of section 1962 of this chapter by issuing appropriate orders, including, but not limited to: ordering any person to divest himself of any interest, direct or indirect, in any enterprise; imposing reasonable restrictions on the future activities or investments of any person, including, but not limited to, prohibiting any person from engaging in the same type of endeavor as the enterprise engaged in, the activities of which affect interstate or foreign commerce; or ordering dissolution or reorganization of any enterprise, making due provision for the rights of innocent persons."],[0,"(b) The Attorney General may institute proceedings under this section. Pending final determination thereof, the court may at any time enter such restraining orders or prohibitions, or take such other actions, including the acceptance of satisfactory performance bonds, as it shall deem proper."],[0,"(c) Any person injured in his business or property by reason of a violation of section 1962 of this chapter may sue therefor in any appropriate United States district court and shall recover threefold the damages he sustains and the cost of the suit, including a reasonable attorney's fee, except that no person may rely upon any conduct that would have been actionable as fraud in the purchase or sale of securities to establish a violation of section 1962. The exception contained in the preceding sentence does not apply to an action against any person that is criminally convicted in connection with the fraud, in which case the statute of limitations shall start to run on the date on which the conviction becomes final."],[0,"(d) A final judgment or decree rendered in favor of the United States in any criminal proceeding brought by the United States under this chapter shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding brought by the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1964?type=usc&year=mostrecent&link-type=html"},"head":"§1964. Civil remedies","tname":"Crimes and Criminal Procedure","by":{"0":"18, 19","2":"3"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"0":"19"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"0":"19","2":"4, 5"}},{"t":"usc","label":"15 U.S.C. § 78dd","url":"https://www.law.cornell.edu/uscode/text/15/78dd","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"18 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/18/2701","subs":["(a)","(c)(1)","(c)(3)","(a)(1)"],"stext":{"head":"§2701. Unlawful access to stored communications","paras":[[0,"(a) Offense.—Except as provided in subsection (c) of this section whoever—"],[1,"(1) intentionally accesses without authorization a facility through which an electronic communication service is provided; or"],[1,"(2) intentionally exceeds an authorization to access that facility;"],[0,"and thereby obtains, alters, or prevents authorized access to a wire or electronic communication while it is in electronic storage in such system shall be punished as provided in subsection (b) of this section."],[0,"(b) Punishment.—The punishment for an offense under subsection (a) of this section is—"],[1,"(1) if the offense is committed for purposes of commercial advantage, malicious destruction or damage, or private commercial gain, or in furtherance of any criminal or tortious act in violation of the Constitution or laws of the United States or any State—"],[2,"(A) a fine under this title or imprisonment for not more than 5 years, or both, in the case of a first offense under this subparagraph; and"],[2,"(B) a fine under this title or imprisonment for not more than 10 years, or both, for any subsequent offense under this subparagraph; and"],[1,"(2) in any other case—"],[2,"(A) a fine under this title or imprisonment for not more than 1 year or both, in the case of a first offense under this paragraph; and"],[2,"(B) a fine under this title or imprisonment for not more than 5 years, or both, in the case of an offense under this subparagraph that occurs after a conviction of another offense under this section."],[0,"(c) Exceptions.—Subsection (a) of this section does not apply with respect to conduct authorized—"],[1,"(1) by the person or entity providing a wire or electronic communications service;"],[1,"(2) by a user of that service with respect to a communication of or intended for that user; or"],[1,"(3) in section 2703, 2704 or 2518 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2701?type=usc&year=mostrecent&link-type=html"},"head":"§2701. Unlawful access to stored communications","tname":"Crimes and Criminal Procedure","by":{"0":"2, 2, 2, 3, 3","1":"5, 11, 12, 22, 23, 24, 5, 11, 12, 22, 23, 24, 23, 5, 23","2":"3, 4, 7, 8, 4, 4, 10"}},{"t":"usc","label":"18 U.S.C. § 2702","url":"https://www.law.cornell.edu/uscode/text/18/2702","subs":["(a)","(a)(1)","(b)(2)","(b)(4)","(c)(1)","(c)(3)","(c)","(b)"],"stext":{"head":"§2702. Voluntary disclosure of customer communications or records","paras":[[0,"(a) Prohibitions.—Except as provided in subsection (b) or (c)—"],[1,"(1) a person or entity providing an electronic communication service to the public shall not knowingly divulge to any person or entity the contents of a communication while in electronic storage by that service; and"],[1,"(2) a person or entity providing remote computing service to the public shall not knowingly divulge to any person or entity the contents of any communication which is carried or maintained on that service—"],[2,"(A) on behalf of, and received by means of electronic transmission from (or created by means of computer processing of communications received by means of electronic transmission from), a subscriber or customer of such service;"],[2,"(B) solely for the purpose of providing storage or computer processing services to such subscriber or customer, if the provider is not authorized to access the contents of any such communications for purposes of providing any services other than storage or computer processing; and"],[1,"(3) a provider of remote computing service or electronic communication service to the public shall not knowingly divulge a record or other information pertaining to a subscriber to or customer of such service (not including the contents of communications covered by paragraph (1) or (2)) to any governmental entity."],[0,"(b) Exceptions for disclosure of communications.—A provider described in subsection (a) may divulge the contents of a communication—"],[1,"(1) to an addressee or intended recipient of such communication or an agent of such addressee or intended recipient;"],[1,"(2) as otherwise authorized in section 2517, 2511(2)(a), or 2703 of this title;"],[1,"(3) with the lawful consent of the originator or an addressee or intended recipient of such communication, or the subscriber in the case of remote computing service;"],[1,"(4) to a person employed or authorized or whose facilities are used to forward such communication to its destination;"],[1,"(5) as may be necessarily incident to the rendition of the service or to the protection of the rights or property of the provider of that service;"],[1,"(6) to the National Center for Missing and Exploited Children, in connection with a report submitted thereto under section 2258A;"],[1,"(7) to a law enforcement agency—"],[2,"(A) if the contents—"],[3,"(i) were inadvertently obtained by the service provider; and"],[3,"(ii) appear to pertain to the commission of a crime; or"],[2,"[(B) Repealed. Pub. L. 108–21, title V, §508(b)(1)(A), Apr. 30, 2003, 117 Stat. 684]"],[1,"(8) to a governmental entity, if the provider, in good faith, believes that an emergency involving danger of death or serious physical injury to any person requires disclosure without delay of communications relating to the emergency; or"],[1,"(9) to a foreign government pursuant to an order from a foreign government that is subject to an executive agreement that the Attorney General has determined and certified to Congress satisfies section 2523."],[0,"(c) Exceptions for Disclosure of Customer Records.—A provider described in subsection (a) may divulge a record or other information pertaining to a subscriber to or customer of such service (not including the contents of communications covered by subsection (a)(1) or (a)(2))—"],[1,"(1) as otherwise authorized in section 2703;"],[1,"(2) with the lawful consent of the customer or subscriber;"],[1,"(3) as may be necessarily incident to the rendition of the service or to the protection of the rights or property of the provider of that service;"],[1,"(4) to a governmental entity, if the provider, in good faith, believes that an emergency involving danger of death or serious physical injury to any person requires disclosure without delay of information relating to the emergency;"],[1,"(5) to the National Center for Missing and Exploited Children, in connection with a report submitted thereto under section 2258A;"],[1,"(6) to any person other than a governmental entity; or"],[1,"(7) to a foreign government pursuant to an order from a foreign government that is subject to an executive agreement that the Attorney General has determined and certified to Congress satisfies section 2523."],[0,"(d) Reporting of Emergency Disclosures.—On an annual basis, the Attorney General shall submit to the Committee on the Judiciary of the House of Representatives and the Committee on the Judiciary of the Senate a report containing—"],[1,"(1) the number of accounts from which the Department of Justice has received voluntary disclosures under subsection (b)(8);"],[1,"(2) a summary of the basis for disclosure in those instances where—"],[2,"(A) voluntary disclosures under subsection (b)(8) were made to the Department of Justice; and"],[2,"(B) the investigation pertaining to those disclosures was closed without the filing of criminal charges; and"],[1,"(3) the number of accounts from which the Department of Justice has received voluntary disclosures under subsection (c)(4)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2702?type=usc&year=mostrecent&link-type=html"},"head":"§2702. Voluntary disclosure of customer communications or records","tname":"Crimes and Criminal Procedure","by":{"0":"3, 3, 3, 3, 3, 3, 3","1":"5, 11, 12, 23, 24, 29, 30, 31, 23, 5, 23, 29, 45","2":"4, 7, 8, 4, 4, 10, 10"}},{"t":"usc","label":"18 U.S.C. § 2703","url":"https://www.law.cornell.edu/uscode/text/18/2703","subs":["(a)","(b)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(b)(1)(B)(i)","(b)(1)(B)(ii)","(c)","(c)(1)","(c)(1)(A)","(c)(2)","(d)","(e)","(g)"],"stext":{"head":"§2703. Required disclosure of customer communications or records","paras":[[0,"(a) Contents of Wire or Electronic Communications in Electronic Storage.—A governmental entity may require the disclosure by a provider of electronic communication service of the contents of a wire or electronic communication, that is in electronic storage in an electronic communications system for one hundred and eighty days or less, only pursuant to a warrant issued using the procedures described in the Federal Rules of Criminal Procedure (or, in the case of a State court, issued using State warrant procedures and, in the case of a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice), issued under section 846 of that title, in accordance with regulations prescribed by the President) by a court of competent jurisdiction. A governmental entity may require the disclosure by a provider of electronic communications services of the contents of a wire or electronic communication that has been in electronic storage in an electronic communications system for more than one hundred and eighty days by the means available under subsection (b) of this section."],[0,"(b) Contents of Wire or Electronic Communications in a Remote Computing Service.—(1) A governmental entity may require a provider of remote computing service to disclose the contents of any wire or electronic communication to which this paragraph is made applicable by paragraph (2) of this subsection—"],[1,"(A) without required notice to the subscriber or customer, if the governmental entity obtains a warrant issued using the procedures described in the Federal Rules of Criminal Procedure (or, in the case of a State court, issued using State warrant procedures and, in the case of a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice), issued under section 846 of that title, in accordance with regulations prescribed by the President) by a court of competent jurisdiction; or"],[1,"(B) with prior notice from the governmental entity to the subscriber or customer if the governmental entity—"],[2,"(i) uses an administrative subpoena authorized by a Federal or State statute or a Federal or State grand jury or trial subpoena; or"],[2,"(ii) obtains a court order for such disclosure under subsection (d) of this section;"],[1,"except that delayed notice may be given pursuant to section 2705 of this title."],[0,"(2) Paragraph (1) is applicable with respect to any wire or electronic communication that is held or maintained on that service—"],[1,"(A) on behalf of, and received by means of electronic transmission from (or created by means of computer processing of communications received by means of electronic transmission from), a subscriber or customer of such remote computing service; and"],[1,"(B) solely for the purpose of providing storage or computer processing services to such subscriber or customer, if the provider is not authorized to access the contents of any such communications for purposes of providing any services other than storage or computer processing."],[0,"(c) Records Concerning Electronic Communication Service or Remote Computing Service.—(1) A governmental entity may require a provider of electronic communication service or remote computing service to disclose a record or other information pertaining to a subscriber to or customer of such service (not including the contents of communications) only when the governmental entity—"],[1,"(A) obtains a warrant issued using the procedures described in the Federal Rules of Criminal Procedure (or, in the case of a State court, issued using State warrant procedures and, in the case of a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice), issued under section 846 of that title, in accordance with regulations prescribed by the President) by a court of competent jurisdiction;"],[1,"(B) obtains a court order for such disclosure under subsection (d) of this section;"],[1,"(C) has the consent of the subscriber or customer to such disclosure;"],[1,"(D) submits a formal written request relevant to a law enforcement investigation concerning telemarketing fraud for the name, address, and place of business of a subscriber or customer of such provider, which subscriber or customer is engaged in telemarketing (as such term is defined in section 2325 of this title); or"],[1,"(E) seeks information under paragraph (2)."],[0,"(2) A provider of electronic communication service or remote computing service shall disclose to a governmental entity the—"],[1,"(A) name;"],[1,"(B) address;"],[1,"(C) local and long distance telephone connection records, or records of session times and durations;"],[1,"(D) length of service (including start date) and types of service utilized;"],[1,"(E) telephone or instrument number or other subscriber number or identity, including any temporarily assigned network address; and"],[1,"(F) means and source of payment for such service (including any credit card or bank account number),"],[0,"of a subscriber to or customer of such service when the governmental entity uses an administrative subpoena authorized by a Federal or State statute or a Federal or State grand jury or trial subpoena or any means available under paragraph (1)."],[0,"(3) A governmental entity receiving records or information under this subsection is not required to provide notice to a subscriber or customer."],[0,"(d) Requirements for Court Order.—A court order for disclosure under subsection (b) or (c) may be issued by any court that is a court of competent jurisdiction and shall issue only if the governmental entity offers specific and articulable facts showing that there are reasonable grounds to believe that the contents of a wire or electronic communication, or the records or other information sought, are relevant and material to an ongoing criminal investigation. In the case of a State governmental authority, such a court order shall not issue if prohibited by the law of such State. A court issuing an order pursuant to this section, on a motion made promptly by the service provider, may quash or modify such order, if the information or records requested are unusually voluminous in nature or compliance with such order otherwise would cause an undue burden on such provider."],[0,"(e) No Cause of Action Against a Provider Disclosing Information Under This Chapter.—No cause of action shall lie in any court against any provider of wire or electronic communication service, its officers, employees, agents, or other specified persons for providing information, facilities, or assistance in accordance with the terms of a court order, warrant, subpoena, statutory authorization, or certification under this chapter."],[0,"(f) Requirement To Preserve Evidence.—"],[1,"(1) In general.—A provider of wire or electronic communication services or a remote computing service, upon the request of a governmental entity, shall take all necessary steps to preserve records and other evidence in its possession pending the issuance of a court order or other process."],[1,"(2) Period of retention.—Records referred to in paragraph (1) shall be retained for a period of 90 days, which shall be extended for an additional 90-day period upon a renewed request by the governmental entity."],[0,"(g) Presence of Officer Not Required.—Notwithstanding section 3105 of this title, the presence of an officer shall not be required for service or execution of a search warrant issued in accordance with this chapter requiring disclosure by a provider of electronic communications service or remote computing service of the contents of communications or records or other information pertaining to a subscriber to or customer of such service."],[0,"(h) Comity Analysis and Disclosure of Information Regarding Legal Process Seeking Contents of Wire or Electronic Communication.—"],[1,"(1) Definitions.—In this subsection—"],[2,"(A) the term \"qualifying foreign government\" means a foreign government—"],[3,"(i) with which the United States has an executive agreement that has entered into force under section 2523; and"],[3,"(ii) the laws of which provide to electronic communication service providers and remote computing service providers substantive and procedural opportunities similar to those provided under paragraphs (2) and (5); and"],[2,"(B) the term \"United States person\" has the meaning given the term in section 2523."],[1,"(2) Motions to quash or modify.—(A) A provider of electronic communication service to the public or remote computing service, including a foreign electronic communication service or remote computing service, that is being required to disclose pursuant to legal process issued under this section the contents of a wire or electronic communication of a subscriber or customer, may file a motion to modify or quash the legal process where the provider reasonably believes—"],[2,"(i) that the customer or subscriber is not a United States person and does not reside in the United States; and"],[2,"(ii) that the required disclosure would create a material risk that the provider would violate the laws of a qualifying foreign government."],[2,"Such a motion shall be filed not later than 14 days after the date on which the provider was served with the legal process, absent agreement with the government or permission from the court to extend the deadline based on an application made within the 14 days. The right to move to quash is without prejudice to any other grounds to move to quash or defenses thereto, but it shall be the sole basis for moving to quash on the grounds of a conflict of law related to a qualifying foreign government."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2703?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2703. Required disclosure of customer communications or records","tname":"Crimes and Criminal Procedure","by":{"0":"3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3","1":"passim, i, 6, 8, 23, 45, 46, 47, 48, 48, 64, 45, 48, 6, 45, 6, 29, 48, 23, 6, 12, 27, 29, 32, 47","2":"passim, 4, 6, 1, 13, 14, 1, 13, 14, 5, 13, 1, 6, 10, 15"}},{"t":"usc","label":"18 U.S.C. § 2705","url":"https://www.law.cornell.edu/uscode/text/18/2705","subs":["(a)"],"by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 2707","url":"https://www.law.cornell.edu/uscode/text/18/2707","stext":{"head":"§2707. Civil action","paras":[[0,"(a) Cause of Action.—Except as provided in section 2703(e), any provider of electronic communication service, subscriber, or other person aggrieved by any violation of this chapter in which the conduct constituting the violation is engaged in with a knowing or intentional state of mind may, in a civil action, recover from the person or entity, other than the United States, which engaged in that violation such relief as may be appropriate."],[0,"(b) Relief.—In a civil action under this section, appropriate relief includes—"],[1,"(1) such preliminary and other equitable or declaratory relief as may be appropriate;"],[1,"(2) damages under subsection (c); and"],[1,"(3) a reasonable attorney's fee and other litigation costs reasonably incurred."],[0,"(c) Damages.—The court may assess as damages in a civil action under this section the sum of the actual damages suffered by the plaintiff and any profits made by the violator as a result of the violation, but in no case shall a person entitled to recover receive less than the sum of $1,000. If the violation is willful or intentional, the court may assess punitive damages. In the case of a successful action to enforce liability under this section, the court may assess the costs of the action, together with reasonable attorney fees determined by the court."],[0,"(d) Administrative Discipline.—If a court or appropriate department or agency determines that the United States or any of its departments or agencies has violated any provision of this chapter, and the court or appropriate department or agency finds that the circumstances surrounding the violation raise serious questions about whether or not an officer or employee of the United States acted willfully or intentionally with respect to the violation, the department or agency shall, upon receipt of a true and correct copy of the decision and findings of the court or appropriate department or agency promptly initiate a proceeding to determine whether disciplinary action against the officer or employee is warranted. If the head of the department or agency involved determines that disciplinary action is not warranted, he or she shall notify the Inspector General with jurisdiction over the department or agency concerned and shall provide the Inspector General with the reasons for such determination."],[0,"(e) Defense.—A good faith reliance on—"],[1,"(1) a court warrant or order, a grand jury subpoena, a legislative authorization, or a statutory authorization (including a request of a governmental entity under section 2703(f) of this title);"],[1,"(2) a request of an investigative or law enforcement officer under section 2518(7) of this title; or"],[1,"(3) a good faith determination that section 2511(3), section 2702(b)(9), or section 2702(c)(7) of this title permitted the conduct complained of;"],[0,"is a complete defense to any civil or criminal action brought under this chapter or any other law."],[0,"(f) Limitation.—A civil action under this section may not be commenced later than two years after the date upon which the claimant first discovered or had a reasonable opportunity to discover the violation."],[0,"(g) Improper Disclosure.—Any willful disclosure of a \"record\", as that term is defined in section 552a(a) of title 5, United States Code, obtained by an investigative or law enforcement officer, or a governmental entity, pursuant to section 2703 of this title, or from a device installed pursuant to section 3123 or 3125 of this title, that is not a disclosure made in the proper performance of the official functions of the officer or governmental entity making the disclosure, is a violation of this chapter. This provision shall not apply to information previously lawfully disclosed (prior to the commencement of any civil or administrative proceeding under this chapter) to the public by a Federal, State, or local governmental entity or by the plaintiff in a civil action under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2707?type=usc&year=mostrecent&link-type=html"},"head":"§2707. Civil action","tname":"Crimes and Criminal Procedure","by":{"0":"8","1":"23, 31"}},{"t":"usc","label":"18 U.S.C. § 2711","url":"https://www.law.cornell.edu/uscode/text/18/2711","subs":["(2)","(3)(A)","(4)"],"stext":{"head":"§2711. Definitions for chapter","paras":[[0,"As used in this chapter—"],[1,"(1) the terms defined in section 2510 of this title have, respectively, the definitions given such terms in that section;"],[1,"(2) the term \"remote computing service\" means the provision to the public of computer storage or processing services by means of an electronic communications system;"],[1,"(3) the term \"court of competent jurisdiction\" includes—"],[2,"(A) any district court of the United States (including a magistrate judge of such a court) or any United States court of appeals that—"],[3,"(i) has jurisdiction over the offense being investigated;"],[3,"(ii) is in or for a district in which the provider of a wire or electronic communication service is located or in which the wire or electronic communications, records, or other information are stored; or"],[3,"(iii) is acting on a request for foreign assistance pursuant to section 3512 of this title;"],[2,"(B) a court of general criminal jurisdiction of a State authorized by the law of that State to issue search warrants; or"],[2,"(C) a court-martial or other proceeding under chapter 47 of title 10 (the Uniform Code of Military Justice) to which a military judge has been detailed; and"],[1,"(4) the term \"governmental entity\" means a department or agency of the United States or any State or political subdivision thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2711?type=usc&year=mostrecent&link-type=html"},"head":"§2711. Definitions for chapter","tname":"Crimes and Criminal Procedure","by":{"0":"24, 24","1":"5, 15, 26, 27","2":"6"}},{"t":"usc","label":"18 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/18/1","by":{"0":"24"}},{"t":"usc","label":"18 U.S.C. § 3105","url":"https://www.law.cornell.edu/uscode/text/18/3105","stext":{"head":"§3105. Persons authorized to serve search warrant","paras":[[0,"A search warrant may in all cases be served by any of the officers mentioned in its direction or by an officer authorized by law to serve such warrant, but by no other person, except in aid of the officer on his requiring it, he being present and acting in its execution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3105?type=usc&year=mostrecent&link-type=html"},"head":"§3105. Persons authorized to serve search warrant","tname":"Crimes and Criminal Procedure","by":{"0":"35","1":"6"}},{"t":"case","label":"Federal Cases Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"BedRoc Ltd. v. United States","cite":"541 U.S. 176","y":2004,"id":"2003/02-1593","sc":1,"sum":"The Court ruled that because sand and gravel were not commercially valuable in 1919 when the Pittman Act was passed, they were not \"valuable minerals\" covered under the Act.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Benz v. Compania Naviera Hidlago, S.A.","cite":"353 U.S. 138","y":1957,"id":"1956/204","sc":1,"sum":"The Labor Management Relations Act of 1947 does not apply to a controversy involving damages resulting from the picketing of a foreign ship operated entirely by foreign seamen under foreign articles while the vessel is temporarily in an American port, though American unions to which the foreign seamen did not belong participated in the picketing; and the Act therefore does not preclude a remedy under state law for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"52"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10, 14, 27, 38, 54"}},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"1":"15, 16, 40, 53","2":"23"}},{"t":"case","label":"Katz v. United States","cite":"389 U.S. 347","y":1967,"id":"1967/35","sc":1,"sum":"The Court found that the government putting a tap on a public payphone is a violation of the users' Fourth Amendment rights.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Kyllo v. United States","cite":"533 U.S. 27","y":2001,"id":"2000/99-8508","sc":1,"sum":"The Court found the use of thermal-imaging to detect areas of high heat in one's private home was a violation of the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Mastafa v. Chevron Corp.","cite":"770 F.3d 170","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/770/170/","by":{"1":"37"}},{"t":"case","label":"Rakas v. Illinois","cite":"439 U.S. 128","y":1978,"id":"1978/77-5781","sc":1,"sum":"1. \"Fourth Amendment rights are personal rights which... may not be vicariously asserted,\" Alderman v. United States, 394 U. S. 165, 174, and a person aggrieved by an illegal search and seizure only through the introduction of damaging evidence secured by a search of a third person's premises or property has not had any of his Fourth Amendment rights infringed. The rule of standing to raise vicarious Fourth …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36","2":"12"}},{"t":"case","label":"Riley v. California","cite":"134 S. Ct. 2473","y":2014,"id":"2013/13-132","sc":1,"sum":"The Court found that the San Diego Police Department's search of an arrested gang member's cell phone pictures without a warrant violated the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"3, 36, 51"}},{"t":"case","label":"United States v. Ackerman","cite":"831 F.3d 1292","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/1292/","by":{"1":"35"}},{"t":"case","label":"United States v. Bach","cite":"310 F.3d 1063","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/310/1063/","by":{"1":"35, 47"}},{"t":"case","label":"United States v. Comprehensive Drug Testing, Inc.","cite":"621 F.3d 1162","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/621/1162/","by":{"1":"35"}},{"t":"case","label":"United States v. Gorshkov","cite":"2001 WL 1024026","y":2001,"court":"W.D. Wash. May 23","by":{"1":"36"}},{"t":"case","label":"United States v. Miller","cite":"425 U.S. 435","y":1976,"id":"1975/74-1179","sc":1,"sum":"The Court reversed the Fifth Circuit and held that Miller had no right to privacy in his bank records. Writing for the majority, Justice Lewis F. Powell asserted that the \"documents subpoenaed are not [Miller's] 'private papers',\" but instead, part of the bank's business records.","sumSrc":"Oyez","by":{"1":"5, 23"}},{"t":"case","label":"United States v. U.S. Dist. Court for the E. Dist. of Mich.","cite":"407 U.S. 297","y":1972,"id":"1971/70-153","sc":1,"sum":"The Court held government officials were obligated to obtain a warrant before beginning electronic surveillance even if domestic security issues were involved. The \"inherent vagueness of the domestic security concept\" and the potential for abusing it to quell political dissent made the Fourth Amendment protections especially important when the government engaged in spying on its own citizens.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"United States v. Warshak","cite":"631 F.3d 266","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/631/266/","sum":"Explaining the now-outdated justification for the six-month rule.","sumSrc":"brief:1","by":{"1":"6, 34, 35, 49","2":"14"}},{"t":"case","label":"Utility Air Regulatory Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Weinberger v. Rossi","cite":"456 U.S. 25","y":1982,"id":"1981/80-1924","sc":1,"sum":"The word \"treaty\" as used in § 106 includes executive agreements, such as the one involved here, and is not limited to those international agreements concluded by the President with the advice and consent of the Senate pursuant to Art. II, § 2, cl. 2, of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"4, 6, 22, 26, 36","2":"14"}},{"t":"usc","label":"18 U.S.C. § 1030","url":"https://www.law.cornell.edu/uscode/text/18/1030","subs":["(e)(2)(B)","(a)(2)(C)"],"stext":{"head":"§1030. Fraud and related activity in connection with computers","paras":[[0,"(a) Whoever—"],[1,"(1) having knowingly accessed a computer without authorization or exceeding authorized access, and by means of such conduct having obtained information that has been determined by the United States Government pursuant to an Executive order or statute to require protection against unauthorized disclosure for reasons of national defense or foreign relations, or any restricted data, as defined in paragraph y. of section 11 of the Atomic Energy Act of 1954, with reason to believe that such information so obtained could be used to the injury of the United States, or to the advantage of any foreign nation willfully communicates, delivers, transmits, or causes to be communicated, delivered, or transmitted, or attempts to communicate, deliver, transmit or cause to be communicated, delivered, or transmitted the same to any person not entitled to receive it, or willfully retains the same and fails to deliver it to the officer or employee of the United States entitled to receive it;"],[1,"(2) intentionally accesses a computer without authorization or exceeds authorized access, and thereby obtains—"],[2,"(A) information contained in a financial record of a financial institution, or of a card issuer as defined in section 1602(n) 1 of title 15, or contained in a file of a consumer reporting agency on a consumer, as such terms are defined in the Fair Credit Reporting Act (15 U.S.C. 1681 et seq.);"],[2,"(B) information from any department or agency of the United States; or"],[2,"(C) information from any protected computer;"],[1,"(3) intentionally, without authorization to access any nonpublic computer of a department or agency of the United States, accesses such a computer of that department or agency that is exclusively for the use of the Government of the United States or, in the case of a computer not exclusively for such use, is used by or for the Government of the United States and such conduct affects that use by or for the Government of the United States;"],[1,"(4) knowingly and with intent to defraud, accesses a protected computer without authorization, or exceeds authorized access, and by means of such conduct furthers the intended fraud and obtains anything of value, unless the object of the fraud and the thing obtained consists only of the use of the computer and the value of such use is not more than $5,000 in any 1-year period;"],[1,"(5)(A) knowingly causes the transmission of a program, information, code, or command, and as a result of such conduct, intentionally causes damage without authorization, to a protected computer;"],[1,"(B) intentionally accesses a protected computer without authorization, and as a result of such conduct, recklessly causes damage; or"],[1,"(C) intentionally accesses a protected computer without authorization, and as a result of such conduct, causes damage and loss.2"],[1,"(6) knowingly and with intent to defraud traffics (as defined in section 1029) in any password or similar information through which a computer may be accessed without authorization, if—"],[2,"(A) such trafficking affects interstate or foreign commerce; or"],[2,"(B) such computer is used by or for the Government of the United States; 3"],[1,"(7) with intent to extort from any person any money or other thing of value, transmits in interstate or foreign commerce any communication containing any—"],[2,"(A) threat to cause damage to a protected computer;"],[2,"(B) threat to obtain information from a protected computer without authorization or in excess of authorization or to impair the confidentiality of information obtained from a protected computer without authorization or by exceeding authorized access; or"],[2,"(C) demand or request for money or other thing of value in relation to damage to a protected computer, where such damage was caused to facilitate the extortion;"],[0,"shall be punished as provided in subsection (c) of this section."],[0,"(b) Whoever conspires to commit or attempts to commit an offense under subsection (a) of this section shall be punished as provided in subsection (c) of this section."],[0,"(c) The punishment for an offense under subsection (a) or (b) of this section is—"],[1,"(1)(A) a fine under this title or imprisonment for not more than ten years, or both, in the case of an offense under subsection (a)(1) of this section which does not occur after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph; and"],[1,"(B) a fine under this title or imprisonment for not more than twenty years, or both, in the case of an offense under subsection (a)(1) of this section which occurs after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(2)(A) except as provided in subparagraph (B), a fine under this title or imprisonment for not more than one year, or both, in the case of an offense under subsection (a)(2), (a)(3), or (a)(6) of this section which does not occur after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(B) a fine under this title or imprisonment for not more than 5 years, or both, in the case of an offense under subsection (a)(2), or an attempt to commit an offense punishable under this subparagraph, if—"],[2,"(i) the offense was committed for purposes of commercial advantage or private financial gain;"],[2,"(ii) the offense was committed in furtherance of any criminal or tortious act in violation of the Constitution or laws of the United States or of any State; or"],[2,"(iii) the value of the information obtained exceeds $5,000; and"],[1,"(C) a fine under this title or imprisonment for not more than ten years, or both, in the case of an offense under subsection (a)(2), (a)(3) or (a)(6) of this section which occurs after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(3)(A) a fine under this title or imprisonment for not more than five years, or both, in the case of an offense under subsection (a)(4) or (a)(7) of this section which does not occur after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph; and"],[1,"(B) a fine under this title or imprisonment for not more than ten years, or both, in the case of an offense under subsection (a)(4),4 or (a)(7) of this section which occurs after a conviction for another offense under this section, or an attempt to commit an offense punishable under this subparagraph;"],[1,"(4)(A) except as provided in subparagraphs (E) and (F), a fine under this title, imprisonment for not more than 5 years, or both, in the case of—"],[2,"(i) an offense under subsection (a)(5)(B), which does not occur after a conviction for another offense under this section, if the offense caused (or, in the case of an attempted offense, would, if completed, have caused)—"],[3,"(I) loss to 1 or more persons during any 1-year period (and, for purposes of an investigation, prosecution, or other proceeding brought by the United States only, loss resulting from a related course of conduct affecting 1 or more other protected computers) aggregating at least $5,000 in value;"],[3,"(II) the modification or impairment, or potential modification or impairment, of the medical examination, diagnosis, treatment, or care of 1 or more individuals;"],[3,"(III) physical injury to any person;"],[3,"(IV) a threat to public health or safety;"],[3,"(V) damage affecting a computer used by or for an entity of the United States Government in furtherance of the administration of justice, national defense, or national security; or"],[3,"(VI) damage affecting 10 or more protected computers during any 1-year period; or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(B) except as provided in subparagraphs (E) and (F), a fine under this title, imprisonment for not more than 10 years, or both, in the case of—"],[2,"(i) an offense under subsection (a)(5)(A), which does not occur after a conviction for another offense under this section, if the offense caused (or, in the case of an attempted offense, would, if completed, have caused) a harm provided in subclauses (I) through (VI) of subparagraph (A)(i); or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(C) except as provided in subparagraphs (E) and (F), a fine under this title, imprisonment for not more than 20 years, or both, in the case of—"],[2,"(i) an offense or an attempt to commit an offense under subparagraphs (A) or (B) of subsection (a)(5) that occurs after a conviction for another offense under this section; or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(D) a fine under this title, imprisonment for not more than 10 years, or both, in the case of—"],[2,"(i) an offense or an attempt to commit an offense under subsection (a)(5)(C) that occurs after a conviction for another offense under this section; or"],[2,"(ii) an attempt to commit an offense punishable under this subparagraph;"],[1,"(E) if the offender attempts to cause or knowingly or recklessly causes serious bodily injury from conduct in violation of subsection (a)(5)(A), a fine under this title, imprisonment for not more than 20 years, or both;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1030?type=usc&year=mostrecent&link-type=html"},"head":"§1030. Fraud and related activity in connection with computers","tname":"Crimes and Criminal Procedure","by":{"1":"18","2":"8"}},{"t":"usc","label":"18 U.S.C. § 2706","url":"https://www.law.cornell.edu/uscode/text/18/2706","subs":["(a)"],"by":{"1":"6, 33"}},{"t":"usc","label":"18 U.S.C. § 3486","url":"https://www.law.cornell.edu/uscode/text/18/3486","by":{"1":"46"}},{"t":"law","label":"Pub. L. No. 111-79","url":"https://www.govinfo.gov/link/plaw/111/public/79","by":{"1":"18"}},{"t":"law","label":"USA PATRIOT Act, Pub. L. No. 107-56","url":"https://www.govinfo.gov/link/plaw/107/public/56","by":{"1":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 34","url":"https://www.law.cornell.edu/rules/frcp/rule_34","subs":["(a)(1)"],"by":{"1":"46"}},{"t":"rule","label":"Fed. R. Civ. P. 45","url":"https://www.law.cornell.edu/rules/frcp/rule_45","subs":["(a)(1)(A)(iii)"],"by":{"1":"46","2":"14"}},{"t":"rule","label":"Fed. R. Crim. P. 16","url":"https://www.law.cornell.edu/rules/frcrmp/rule_16","subs":["(a)(1)","(b)(1)"],"by":{"1":"46, 46"}},{"t":"rule","label":"Fed. R. Crim. P. 17","url":"https://www.law.cornell.edu/rules/frcrmp/rule_17","subs":["(c)"],"by":{"1":"46"}},{"t":"rule","label":"Fed. R. Crim. P. 41","url":"https://www.law.cornell.edu/rules/frcrmp/rule_41","subs":["(a)","(e)(2)(B)"],"by":{"1":"17, 47, 17, 35"}},{"t":"case","label":"Arizona v. Hicks","cite":"480 U.S. 321","y":1987,"id":"1986/85-1027","sc":1,"sum":"The Court found that the search and seizure of the stereo equipment violated the Fourth and Fourteenth Amendments. Citing the Court's holding in Coolidge v. New Hampshire (1971), Justice Scalia upheld the \"plain view\" doctrine which allows police officers under some circumstances to seize evidence in plain view without a warrant.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Burdeau v. McDowell","cite":"256 U.S. 465","y":1921,"id":"scdb/1920-073","sc":1,"sum":".The Solicitor General for appellant:","sumSrc":"Headnote (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"sum":"The Court held that the law's plain language criminalized the smuggling scheme in this case. The common-law revenue rule did not bar the prosecution of the scheme, because no common-law case as of 1952 clearly established that the rule barred the U.S. from prosecuting a fraudulent scheme to evade foreign taxes.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"United States v. Auernheimer","cite":"748 F.3d 525","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/748/525/","by":{"2":"8"}},{"t":"case","label":"United States v. Dionisio","cite":"410 U.S. 1","y":1973,"id":"1972/71-229","sc":1,"sum":"A grand jury subpoenaed about 20 persons, including respondent, to give voice exemplars for identification purposes. Respondent, on Fourth and Fifth Amendment grounds, refused to comply. The District Court rejected both claims and adjudged respondent in contempt. The Court of Appeals agreed in rejecting respondent's Fifth Amendment claim but reversed on the ground that the Fourth Amendment required a preliminary …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"United States v. Re","cite":"313 F. Supp. 442","y":1970,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./313/442/","by":{"2":"16"}}]};